from taf.ul.ettf.object_provider.provider import provider
from taf.ul.ettf.sim.core.command import Command
from taf.ul.ettf.sim.core.simulator import Simulator, NotConnectedError
from taf.ul.ettf.typed.typed import typed
from taf.ul.ettf.typed.custom_types import IsType
from taf.ul.ettf.utils.timeout import Timeout


DEFAULT_TIMEOUT = 30


class EgateCommand(Command):
    PROMPT = '==(.|\n)*EGATE>'

    def __init__(self, command, validators=None, parser=None, stop_regex=PROMPT):
        super(EgateCommand, self).__init__(command, validators, parser)
        self._stop_regex = stop_regex

    @property
    def stop_regex(self):
        return self._stop_regex


class Egate(Simulator):
    def __init__(self, timeout=DEFAULT_TIMEOUT):
        self._wts = None
        self._timeout = timeout

    def connect(self):
        self._wts = provider.get_egate()
        return self

    @typed(command=IsType(EgateCommand))
    def execute_command(self, command):
        if not self._wts:
            raise NotConnectedError('execute_command called before connection',
                                    'Connect before trying to execute commands')
        with Timeout(timeout=self._timeout):
            return self._wts.execute_egate_command_and_wait_for_data(command.command, pass_regexp=command.stop_regex)
